@import url('https://fonts.googleapis.com/css2?family=Didact+Gothic&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Wes Anderson — symmetrical pastel worlds, precious typographic detail */
.theme-wes-anderson {
  --bg: oklch(0.935 0.032 73.5);
  --surface: oklch(0.966 0.022 74.1);
  --surface-2: oklch(0.904 0.038 73.7);
  --fg: oklch(0.376 0.021 61.4);
  --fg-muted: oklch(0.613 0.034 64.0);
  --accent: oklch(0.679 0.108 10.6);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.696 0.042 192.3);
  --line: oklch(0.853 0.043 74.1);
  --success: oklch(0.696 0.042 192.3);
  --warning: oklch(0.767 0.141 81.6);
  --danger: oklch(0.599 0.132 31.7);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Didact Gothic", sans-serif;
  --font-body: "Didact Gothic", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.08em;
  --label-transform: uppercase;
  --label-tracking: 0.26em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-wes-anderson h1,
.theme-wes-anderson h2,
.theme-wes-anderson h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-wes-anderson h1, .theme-wes-anderson h2, .theme-wes-anderson h3 { text-align: inherit; }
.theme-wes-anderson h2 { border-block: 1px solid var(--fg); padding-block: 0.4rem; display: inline-block; }
.theme-wes-anderson .label-caps { color: var(--accent); }
.theme-wes-anderson button { border: 2px solid var(--fg); }
.theme-wes-anderson ::selection { background: var(--accent-2); color: #ffffff; }

/* alt-mode — Grand Budapest at night: deep plum lobby, pastel pink neon signage */
.theme-wes-anderson.alt-mode {
  --bg: oklch(0.255 0.045 340.0);
  --surface: oklch(0.300 0.050 340.0);
  --surface-2: oklch(0.350 0.055 340.0);
  --fg: oklch(0.930 0.025 74.0);
  --fg-muted: oklch(0.700 0.040 350.0);
  --accent: oklch(0.750 0.115 10.6);
  --accent-fg: oklch(0.220 0.045 340.0);
  --accent-2: oklch(0.760 0.055 192.3);
  --line: oklch(0.500 0.055 345.0 / 60%);
  --success: oklch(0.760 0.055 192.3);
  --warning: oklch(0.800 0.130 82.0);
  --danger: oklch(0.680 0.150 25.0);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 35%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 45%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 55%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 55%, transparent);
}
.theme-wes-anderson.alt-mode h2 { border-block-color: var(--accent); }
.theme-wes-anderson.alt-mode button { border-color: var(--accent); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
